text:
menu.dialog-menu-container {
  list-style-type: none;
  display: flex;
  align-items: center;
  margin-block-end: 0;
  margin-inline: 0;
  padding: 2px 10px;
  justify-content: end;
  background-color: var(--dialog-background-color);
  position: sticky;
  inset-block-end: 0;
  max-inline-size: none;

  &.two-columns {
    justify-content: space-between;
  }

  &.menu-in-body {
    margin-inline: -10px;
  }
}
